using System.Data.Entity;using System.Linq;using System.Net;using System.Web.Mvc;using ClassActivityStudentsApp.Models;
namespace ClassActivityStudentsApp.Controllers{public class StudentsController:Controller{readonly StudentsDbContext db=new StudentsDbContext();public ActionResult Index(){return View(db.Students.AsNoTracking().OrderBy(x=>x.LastName).ToList());}public ActionResult Create(){return View("Edit",new Student{EnrollmentDate=System.DateTime.Today});}[HttpPost,ValidateAntiForgeryToken]public ActionResult Create(Student x){if(!ModelState.IsValid)return View("Edit",x);db.Students.Add(x);db.SaveChanges();return RedirectToAction("Index");}public ActionResult Edit(int? id){if(id==null)return new HttpStatusCodeResult(HttpStatusCode.BadRequest);var x=db.Students.Find(id);return x==null?HttpNotFound():(ActionResult)View(x);}[HttpPost,ValidateAntiForgeryToken]public ActionResult Edit(Student x){if(!ModelState.IsValid)return View(x);db.Entry(x).State=EntityState.Modified;db.SaveChanges();return RedirectToAction("Index");}[HttpPost,ValidateAntiForgeryToken]public ActionResult Delete(int id){var x=db.Students.Find(id);if(x!=null){db.Students.Remove(x);db.SaveChanges();}return RedirectToAction("Index");}protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);}}}
